const body = $('Voice Platform Webhook').item.json.body || $('Voice Platform Webhook').item.json || {};
const msg = body.message || {};
let eventType = 'other';
let toolCallId = '';
let functionName = '';
let args = {};
if (msg.type === 'tool-calls' && Array.isArray(msg.toolCallList) && msg.toolCallList.length) {
  eventType = 'tool-call';
  const tc = msg.toolCallList[0];
  toolCallId = tc.id || '';
  functionName = (tc.function && tc.function.name) ? tc.function.name : '';
  const rawArgs = tc.function ? tc.function.arguments : {};
  args = typeof rawArgs === 'string' ? (() => { try { return JSON.parse(rawArgs); } catch (e) { return {}; } })() : (rawArgs || {});
} else if (msg.type === 'end-of-call-report') {
  eventType = 'end-of-call';
}
const call = msg.call || {};
const artifact = msg.artifact || {};
const analysis = msg.analysis || {};
return { json: { eventType, toolCallId, functionName, args, callId: call.id || '', customerNumber: (call.customer && call.customer.number) ? call.customer.number : '', transcript: artifact.transcript || '', summary: analysis.summary || '', endedReason: msg.endedReason || '', durationSeconds: msg.durationSeconds || 0 } };

const req = $('Normalize Request').first().json;
const cfg = $('Agent Config').first().json;
const slot = Number(cfg.SlotLengthMinutes) || 30;
const items = $input.all();
const busy = [];
for (const it of items) {
  const e = it.json;
  if (e.error) continue;
  const s = e.start && (e.start.dateTime || e.start.date);
  const en = e.end && (e.end.dateTime || e.end.date);
  if (s && en) busy.push({ start: new Date(s), end: new Date(en) });
}
const open = [];
const now = new Date();
for (let d = 0; d < 5 && open.length < 4; d++) {
  for (let h = 9; h < 17 && open.length < 4; h++) {
    const start = new Date(now);
    start.setDate(start.getDate() + d);
    start.setHours(h, 0, 0, 0);
    if (start <= now) continue;
    const end = new Date(start.getTime() + slot * 60000);
    const clash = busy.some(b => start < b.end && end > b.start);
    if (!clash) open.push(start);
  }
}
const spoken = open.length ? open.map(d => d.toLocaleString('en-US', { weekday: 'long', hour: 'numeric', minute: '2-digit' })).join(', ') : '';
const result = open.length ? ('The next available times are: ' + spoken + '. Which works best?') : 'I do not see any open slots in the next five days. Would you like me to take a message instead?';
return [{ json: { toolCallId: req.toolCallId, result } }];

const req = $('Normalize Request').first().json;
const phone = String(req.args.phone || req.customerNumber || '').replace(/[^0-9]/g, '');
const rows = $input.all().map(i => i.json).filter(r => !r.error);
const digits = v => String(v || '').replace(/[^0-9]/g, '');
let match = null;
if (phone.length >= 7) {
  match = rows.find(r => { const d = digits(r.Phone); return d && (d.endsWith(phone.slice(-7)) || phone.endsWith(d.slice(-7))); });
}
const result = match ? ('Found them. Name: ' + (match.Name || 'unknown') + '. Status: ' + (match.Status || 'unknown') + '. Last contact: ' + (match['Last Contact'] || 'not recorded') + '. Notes: ' + (match.Notes || 'none')) : 'I could not find an existing record for this caller. Treat them as a new customer.';
return [{ json: { toolCallId: req.toolCallId, result, matched: !!match } }];

const req = $('Normalize Request').first().json;
const failed = !!$input.item.json.error;
const result = failed ? 'I could not save that just now, but I have made a note and someone will follow up.' : 'Got it, I have logged that request and the team will follow up.';
return { json: { toolCallId: req.toolCallId, result } };

const req = $input.item.json;
const cfg = $('Agent Config').first().json;
const name = req.functionName || 'unnamed';
const result = name === 'transfer_call' ? cfg.TransferMessage : ('I do not have a handler for "' + name + '" yet. Tell the caller you will pass this to a team member.');
return { json: { toolCallId: req.toolCallId, result } };

const r = $input.item.json;
const cfg = $('Agent Config').first().json;
const words = String(cfg.FollowUpKeywords || '').toLowerCase().split(',').map(w => w.trim()).filter(Boolean);
const haystack = (String(r.transcript || '') + ' ' + String(r.summary || '')).toLowerCase();
const hits = words.filter(w => haystack.includes(w));
return { json: { callId: r.callId, caller: r.customerNumber, summary: r.summary || 'No summary provided by the platform.', transcript: String(r.transcript || '').slice(0, 20000), endedReason: r.endedReason, durationSeconds: r.durationSeconds, needsFollowUp: hits.length > 0, flags: hits.join(', ') || 'none' } };

